    INSERT INTO dbo.[ind_actividadescomercio] ([acc_Id], [acc_Anio], [acc_Codigo], [acc_Nombre], [acc_Tarifa], [acc_GrupoTarifa], [acc_Exento], [acc_Estado], [acc_FechaCreacion], [acc_FechaActualizacion]) VALUES
        (1, 2025, '101', 'Producción, procesamiento, transformación y conservación de carnes y pescados y sus derivados.', .004, 1, 0, 1, '2026-03-03T15:02:56', '2026-03-03T15:02:56'),
        (2, 2025, '102', 'Elaboración de alimentos compuestos principalmente de frutas, legumbres y hortalizas, panaderías.', .004, 3, 0, 1, '2026-03-03T15:02:56', '2026-03-03T15:02:56'),
        (3, 2025, '103', 'Productos de calzado, partes de calzado, prendas de vestir, prendas y tejidos en otros materiales.', .004, 3, 0, 1, '2026-03-03T15:02:56', '2026-03-03T15:02:56'),
        (4, 2025, '104', 'Fabricación de artículos confeccionados en cuero natural o recuperado.', .005, 3, 0, 1, '2026-03-03T15:02:56', '2026-03-03T15:02:56'),
        (5, 2025, '105', 'Elaboración de comidas y platos preparados por vendedores informales.', .006, 3, 0, 1, '2026-03-03T15:02:56', '2026-03-03T15:02:56'),
        (6, 2025, '106', 'Fabricación de artículos de vidrio, cerámica, porcelana, hormigón y similares.', .006, 3, 0, 1, '2026-03-03T15:02:56', '2026-03-03T15:02:56'),
        (7, 2025, '107', 'Fabricación de joyas, bisutería y artículos conexos.', .006, 3, 0, 1, '2026-03-03T15:02:56', '2026-03-03T15:02:56'),
        (8, 2025, '108', 'Fabricación de productos de hierro, acero, aluminio y materiales de construcción.', .007, 3, 0, 1, '2026-03-03T15:02:56', '2026-03-03T15:02:56'),
        (9, 2025, '109', 'Fabricación de maquinaria y equipo de uso especial.', .007, 3, 0, 1, '2026-03-03T15:02:56', '2026-03-03T15:02:56'),
        (10, 2025, '110', 'Reciclaje de materiales metálicos y no metálicos.', .007, 3, 0, 1, '2026-03-03T15:02:56', '2026-03-03T15:02:56'),
        (11, 2025, '111', 'Fabricación de bebidas alcohólicas y aguas tratadas.', .007, 3, 0, 1, '2026-03-03T15:02:56', '2026-03-03T15:02:56'),
