    INSERT INTO dbo.[ind_conceptos] ([con_Id], [con_Anio], [con_Codigo], [con_Nombre], [con_Observaciones], [con_Estado], [con_FechaCreacion], [con_FechaActualizacion]) VALUES
        (1, 2026, '1', 'INDUSTRIA Y COMERCIO', 'ROUND(dec_ValorConcepto1,-3)', 1, '2026-01-03T14:46:53', '2026-01-03T14:46:53'),
        (2, 2026, '2', 'AVISOS Y TABLEROS', 'CASE WHEN EXISTS (SELECT 1 FROM ind_contribuyentes c WHERE c.ind_Id = ep.dec_IdContribuyente AND ISNULL(c.ind_SinAvisosTableros, 0) = 1) THEN 0 ELSE ROUND(dec_ValorConcepto1*0.15,-3) END', 1, '2026-01-03T14:46:53', '2026-08-26T17:33:50'),
        (3, 2026, '3', 'SOBRETASA BOMBERIL', 'ROUND(dec_ValorConcepto1*0.05,-3)', 1, '2026-01-03T14:46:53', '2026-01-03T14:46:53'),
        (4, 2026, '4', 'TOTAL IMPUESTO A CARGO', 'dec_ValorConcepto1+dec_ValorConcepto2+dec_ValorConcepto3', 1, '2026-01-03T14:46:53', '2026-01-03T14:46:53'),
        (5, 2026, '5', 'VALOR DE EXENCION O EXONERACION', 'ep.dec_ValorConcepto5', 1, '2026-01-03T14:46:53', '2026-08-21T20:18:38'),
        (6, 2026, '6', '(-) MENOS RETENCIONES', 'ep.dec_ValorConcepto6', 1, '2026-01-03T14:46:53', '2026-08-21T20:18:38'),
        (7, 2026, '7', 'MENOS AUTORETENCIONES', 'ep.dec_ValorConcepto7', 1, '2026-01-03T14:46:53', '2026-08-21T20:18:38'),
        (8, 2026, '8', '(-) ANTICIPO AÑO ANTERIOR', 'ep.dec_ValorConcepto8', 1, '2026-01-03T14:46:53', '2026-08-21T20:18:38'),
        (9, 2026, '9', '(+) ANTICIPO AÑO SIGUIENTE', 'ep.dec_ValorConcepto9', 1, '2026-01-03T14:46:53', '2026-08-21T20:18:38'),
        (10, 2026, '10', 'SANCIONES', 'ep.dec_ValorConcepto10', 1, '2026-01-03T14:46:53', '2026-08-21T20:18:38'),
        (11, 2026, '11', 'SALDO A FAVOR VIGENCIAS ANTERIORES', 'ep.dec_ValorConcepto11', 1, '2026-01-03T14:46:53', '2026-08-21T20:18:38'),
        (12, 2026, '12', 'TOTAL SALDO A CARGO', 'CASE WHEN dec_ValorConcepto4-dec_ValorConcepto5-dec_ValorConcepto6-dec_ValorConcepto7-dec_ValorConcepto8+dec_ValorConcepto9+dec_ValorConcepto10-dec_ValorConcepto11 < 0 THEN 0 ELSE dec_ValorConcepto4-dec_ValorConcepto5-dec_ValorConcepto6-dec_ValorConcepto7-dec_ValorConcepto8+dec_ValorConcepto9+dec_ValorConcepto10-dec_ValorConcepto11 END', 1, '2026-01-03T14:46:53', '2026-08-25T14:19:13'),
        (13, 2026, '13', 'TOTAL SALDO A FAVOR', 'CASE WHEN dec_ValorConcepto4-dec_ValorConcepto5-dec_ValorConcepto6-dec_ValorConcepto7-dec_ValorConcepto8+dec_ValorConcepto9+dec_ValorConcepto10-dec_ValorConcepto11 < 0 
    INSERT INTO dbo.[ind_renglones_retencion] ([ren_Id], [ren_Modulo], [ren_Anio], [ren_Codigo], [ren_Nombre], [ren_Formula], [ren_Manual], [ren_Orden], [ren_Estado]) VALUES
        (1, 'RETEICA', 2026, 14, N'TOTAL VALOR RETENCIONES', N'(SELECT ISNULL(SUM(a.rea_ValorRetencion),0) FROM dbo.ind_reteica_actividades a WHERE a.rea_IdReteica = ep.ret_Id AND a.rea_Activo = 1)', 0, 1, 1),
