        (4, 'RETEICA', 2026, 17, N'TOTAL A PAGAR', N'ISNULL(ep.ret_ValorConcepto14,0) + ISNULL(ep.ret_ValorConcepto15,0) + ISNULL(ep.ret_ValorConcepto16,0)', 0, 4, 1),
        (5, 'AUTORRETEICA', 2026, 9, N'INGRESOS BRUTOS RECIBIDOS EN EL BIMESTRE', N'ep.aut_ValorConcepto9', 1, 1, 1),
        (6, 'AUTORRETEICA', 2026, 10, N'Menos DEVOLUCIONES, REBAJAS Y DESCUENTOS', N'ep.aut_ValorConcepto10', 1, 2, 1),
        (7, 'AUTORRETEICA', 2026, 11, N'Menos DEDUCCIONES, EXENCIONES Y NO SUJECIONES', N'ep.aut_ValorConcepto11', 1, 3, 1),
        (8, 'AUTORRETEICA', 2026, 12, N'Menos INGRESOS FUERA DEL MUNICIPIO', N'ep.aut_ValorConcepto12', 1, 4, 1),
        (9, 'AUTORRETEICA', 2026, 13, N'INGRESOS NETOS GRAVADOS (Renglones 9-10-11-12)', N'ISNULL(ep.aut_ValorConcepto9,0) - ISNULL(ep.aut_ValorConcepto10,0) - ISNULL(ep.aut_ValorConcepto11,0) - ISNULL(ep.aut_ValorConcepto12,0)', 0, 5, 1),
        (10, 'AUTORRETEICA', 2026, 15, N'AUTORRETENCIONES INDUSTRIA Y COMERCIO', N'(SELECT ISNULL(SUM(a.aua_ValorImpuesto),0)
