    INSERT INTO dbo.conf_parametros ([par_Clave], [par_Valor], [par_Nombre], [par_Descripcion], [par_Patron], [par_Estado], [par_FechaActualizacion], [par_Sensible]) VALUES ('RECAUDO_EAN', NULL, N'EAN de recaudo (codigo de barras)', N'Los 13 digitos que identifican el convenio de recaudo del municipio ante el banco. Van dentro del codigo de barras de la declaracion y son los que permiten que un cajero pueda cobrarla. Lo entrega el banco; cada entidad tiene el suyo. Si queda vacio, el codigo de barras se imprime con el numero de declaracion y NO se puede pagar en ventanilla.', '^[0-9]{13}$', 1, NULL, 0);
    INSERT INTO dbo.conf_parametros ([par_Clave], [par_Valor], [par_Nombre], [par_Descripcion], [par_Patron], [par_Estado], [par_FechaActualizacion], [par_Sensible]) VALUES ('RECAUDO_DIAS_VIGENCIA', NULL, N'Dias de vigencia del recibo', N'Cuantos dias vale el codigo de barras desde que se imprime. Se usa para el segmento (96) del codigo. Dejarlo VACIO omite ese segmento, que es lo recomendado mientras el banco no confirme si esa fecha es el vencimiento del recibo. Poner 0 imprime la fecha del dia en que se genera.', '^[0-9]{1,4}$', 1, NULL, 0);
    INSERT INTO dbo.conf_parametros ([par_Clave], [par_Valor], [par_Nombre], [par_Descripcion], [par_Patron], [par_Estado], [par_FechaActualizacion], [par_Sensible]) VALUES ('PASARELA_BASEURL', NULL, N'Dirección de la pasarela de pago', N'La dirección del servicio con el que se cobra por PSE, terminada en /api y sin barra final. La entrega el banco: una para pruebas y otra para producción. Vacío = se usa la del archivo de configuración del servidor.', '^https://[A-Za-z0-9.-]+(/[A-Za-z0-9._~/-]*)?$', 1, NULL, 0);
    INSERT INTO dbo.conf_parametros ([par_Clave], [par_Valor], [par_Nombre], [par_Descripcion], [par_Patron], [par_Estado], [par_FechaActualizacion], [par_Sensible]) VALUES ('PASARELA_LOGIN', NULL, N'Usuario del convenio de recaudo', N'El identificador que entrega el banco junto con la clave secreta. Identifica el convenio de ESTA entidad. Vacío = se usa el del archivo de configuración del servidor.', '^[A-Za-z0-9._-]{8,100}$', 1, NULL, 0);
    INSERT INTO dbo.conf_parametros ([par_Clave], [par_Valor], [par_Nombre], [par_Descripcion], [par_Patron], [par_Estado], [par_FechaActualizacion], [par_Sensible]) VALUES ('PASARELA_SECRETKEY', NULL, N'Clave secreta del convenio de recaudo', N'La clave que entrega el banco con el usuario. No se muestra nunca: solo se indica si está puesta. Para cambiarla, escriba la nueva; dejarla en blanco no la borra. Vacío = se usa la del archivo de configuración del servidor.', '^\S{8,200}$', 1, NULL, 1);
    INSERT INTO dbo.conf_parametros ([par_Clave], [par_Valor], [par_Nombre], [par_Descripcion], [par_Patron], [par_Estado], [par_FechaActualizacion], [par_Sensible]) VALUES ('ICA_FECHA_LIMITE', N'30/04', N'Fecha límite de pago del ICA (día/mes)', N'Día y mes (DD/MM) hasta el que se presenta y paga el ICA sin intereses. Al día siguiente la declaración queda vencida: ya no se imprime con código de barras y se paga con el recibo de pago. Vacío = 30/04.', '^(0?[1-9]|[12][0-9]|3[01])/(0?[1-9]|1[0-2])$', 1, NULL, 0);
    INSERT INTO dbo.conf_parametros ([par_Clave], [par_Valor], [par_Nombre], [par_Descripcion], [par_Patron], [par_Estado], [par_FechaActualizacion], [par_Sensible]) VALUES ('RECIBO_BANCOS', NULL, N'Bancos autorizados (recibo de pago)', N'Se imprimen al pie del recibo de pago como "Páguese en: BANCOS: ...". Escríbalos como BANCO (número de cuenta), separados por comas. Vacío = el recibo no los imprime.', '^[^<>]{0,500}$', 0, NULL, 0);
    INSERT INTO dbo.conf_parametros ([par_Clave], [par_Valor], [par_Nombre], [par_Descripcion], [par_Patron], [par_Estado], [par_FechaActualizacion], [par_Sensible]) VALUES ('PASARELA_PROVEEDOR', N'PLACETOPAY', N'Pasarela de pago en línea', N'Con qué empresa se cobra en línea: PLACETOPAY (AvalPay, PSE) o WOMPI (Bancolombia: PSE, tarjetas, Nequi y los demás medios que el comercio habilite en Wompi). Cada una usa sus propias credenciales.', '^(PLACETOPAY|WOMPI)$', 1, NULL, 0);
    INSERT INTO dbo.conf_parametros ([par_Clave], [par_Valor], [par_Nombre], [par_Descripcion], [par_Patron], [par_Estado], [par_FechaActualizacion], [par_Sensible]) VALUES ('WOMPI_LLAVE_PUBLICA', NULL, N'Wompi: llave pública', N'Empieza por pub_test_ (pruebas) o pub_prod_ (producción). Está en el panel de Wompi del comercio, en Desarrolladores.', '^pub_(test|prod)_[A-Za-z0-9]{8,120}$', 1, NULL, 0);
    INSERT INTO dbo.conf_parametros ([par_Clave], [par_Valor], [par_Nombre], [par_Descripcion], [par_Patron], [par_Estado], [par_FechaActualizacion], [par_Sensible]) VALUES ('WOMPI_LLAVE_PRIVADA', NULL, N'Wompi: llave privada', N'Empieza por prv_test_ o prv_prod_. Con ella el sistema confirma cada pago con Wompi. No se muestra nunca; para cambiarla, escriba la nueva.', '^prv_(test|prod)_[A-Za-z0-9]{8,120}$', 1, NULL, 1);
    INSERT INTO dbo.conf_parametros ([par_Clave], [par_Valor], [par_Nombre], [par_Descripcion], [par_Patron], [par_Estado], [par_FechaActualizacion], [par_Sensible]) VALUES ('WOMPI_SECRETO_INTEGRIDAD', NULL, N'Wompi: secreto de integridad', N'Empieza por test_integrity_ o prod_integrity_. Firma el valor y la referencia de cada pago para que nadie los cambie en el camino. No se muestra nunca.', '^(test|prod)_integrity_[A-Za-z0-9]{8,120}$', 1, NULL, 1);
    INSERT INTO dbo.conf_parametros ([par_Clave], [par_Valor], [par_Nombre], [par_Descripcion], [par_Patron], [par_Estado], [par_FechaActualizacion], [par_Sensible]) VALUES ('WOMPI_SECRETO_EVENTOS', NULL, N'Wompi: secreto de eventos', N'Empieza por test_events_ o prod_events_. Con él se comprueba que los avisos de pago vienen de Wompi. No se muestra nunca.', '^(test|prod)_events_[A-Za-z0-9]{8,120}$', 1, NULL, 1);
    INSERT INTO dbo.conf_parametros ([par_Clave], [par_Valor], [par_Nombre], [par_Descripcion], [par_Patron], [par_Estado], [par_FechaActualizacion], [par_Sensible]) VALUES ('PASARELA_USUARIOS_PRUEBA', NULL, N'Usuarios de prueba del pago en línea', N'Mientras se prueba la pasarela con credenciales de PRUEBAS, solo estos usuarios (números de usuario separados por coma) ven el botón de pago. Vacío = lo ven todos, lo que se quiere en producción. Con las llaves de pruebas de Wompi y este campo vacío no lo ve nadie.', '^[0-9]{1,9}( *, *[0-9]{1,9})*$', 1, NULL, 0);
    INSERT INTO dbo.conf_parametros ([par_Clave], [par_Valor], [par_Nombre], [par_Descripcion], [par_Patron], [par_Estado], [par_FechaActualizacion], [par_Sensible]) VALUES ('PASARELA_BANCO', NULL, N'Banco del pago en línea', N'Banco al que la pasarela (PSE o Wompi) le consigna a la entidad. Cada pago en línea queda con este banco. Al elegirlo, los pagos en línea anteriores sin banco (o con el que estaba elegido antes) quedan con él.', '^[0-9]{1,9}$', 1, NULL, 0);
    INSERT INTO dbo.conf_parametros ([par_Clave], [par_Valor], [par_Nombre], [par_Descripcion], [par_Patron], [par_Estado], [par_FechaActualizacion], [par_Sensible]) VALUES ('RIT_FUNCIONARIO_NOMBRE', NULL, N'Funcionario del RIT: nombre', N'Nombre que sale en la casilla 31 del RIT ("Firma del Funcionario"). Vacío, la casilla queda en blanco para firmar a mano.', '(*UTF8)^.{1,80}$', 1, NULL, 0);
    INSERT INTO dbo.conf_parametros ([par_Clave], [par_Valor], [par_Nombre], [par_Descripcion], [par_Patron], [par_Estado], [par_FechaActualizacion], [par_Sensible]) VALUES ('RIT_FUNCIONARIO_CARGO', NULL, N'Funcionario del RIT: cargo', N'Cargo que sale debajo del nombre en la casilla 31 del RIT, por ejemplo "Director de impuestos".', '(*UTF8)^.{1,80}$', 1, NULL, 0);
    INSERT INTO dbo.ind_consecutivos (cse_Tipo, cse_Anio, cse_Valor, cse_FechaActualizacion) VALUES ('ESTABLECIMIENTO', 0, 1000, GETDATE());
