/* Catálogos de referencia (sin datos de contribuyentes, usuarios, pagos ni claves). Solo se cargan en tablas vacías;
   conf_parametros y ind_consecutivos entran por clave. Tomado de la base de Paipa al nivel de la migración 053,
   con los datos propios de Paipa vaciados (EAN de recaudo, bancos del recibo, cuentas de los bancos).
   OJO: las tarifas de actividades y las fórmulas de conceptos son las de Paipa; cada Alcaldía debe validarlas
   con su Estatuto de Rentas antes de liquidar. */
SET NOCOUNT ON;
SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;
GO
