/* ind_conceptos: 18 filas */
IF NOT EXISTS (SELECT 1 FROM dbo.[ind_conceptos])
BEGIN
    SET IDENTITY_INSERT dbo.[ind_conceptos] ON;
THEN ABS(dec_ValorConcepto4-dec_ValorConcepto5-dec_ValorConcepto6-dec_ValorConcepto7-dec_ValorConcepto8+dec_ValorConcepto9+dec_ValorConcepto10-dec_ValorConcepto11) 
ELSE 0 END', 1, '2026-01-03T14:46:53', '2026-01-03T14:46:53'),
        (14, 2026, '14', 'VALOR A PAGAR', 'CASE WHEN dec_ValorConcepto4-dec_ValorConcepto5-dec_ValorConcepto6-dec_ValorConcepto7-dec_ValorConcepto8+dec_ValorConcepto9+dec_ValorConcepto10-dec_ValorConcepto11 < 0 THEN 0 ELSE dec_ValorConcepto4-dec_ValorConcepto5-dec_ValorConcepto6-dec_ValorConcepto7-dec_ValorConcepto8+dec_ValorConcepto9+dec_ValorConcepto10-dec_ValorConcepto11 END', 1, '2026-01-03T14:46:53', '2026-08-25T14:19:13'),
        (15, 2026, '15', 'DESCUENTO POR PRONTO PAGO', 'ep.dec_ValorConcepto15', 1, '2026-01-03T14:46:53', '2026-08-25T14:19:13'),
        (16, 2026, '16', 'INTERES DE MORA', 'ep.dec_ValorConcepto16', 1, '2026-01-03T14:46:53', '2026-08-21T20:18:38'),
        (17, 2026, '17', 'PAPELERIA MUNICIPAL', 'ep.dec_ValorConcepto17', 1, '2026-01-03T14:46:53', '2026-08-21T20:18:38'),
        (18, 2026, '20', 'TOTAL A PAGAR', 'CASE WHEN dec_ValorConcepto13 > 0 THEN 0 WHEN dec_ValorConcepto14-dec_ValorConcepto15+dec_ValorConcepto16 < 0 THEN 0 ELSE dec_ValorConcepto14-dec_ValorConcepto15+dec_ValorConcepto16 END', 1, '2026-01-03T14:46:53', '2026-09-29T02:43:57');
    SET IDENTITY_INSERT dbo.[ind_conceptos] OFF;
END
GO
/* ind_renglones_retencion: 18 filas */
IF NOT EXISTS (SELECT 1 FROM dbo.[ind_renglones_retencion])
BEGIN
    SET IDENTITY_INSERT dbo.[ind_renglones_retencion] ON;
                          FROM dbo.ind_autorreteica_actividades a
                         WHERE a.aua_IdAutorreteica = ep.aut_Id AND a.aua_Activo = 1)
                     + ISNULL(ep.aut_ImpuestoEnergia,0)', 0, 6, 1),
        (11, 'AUTORRETEICA', 2026, 16, N'AUTORRETENCIONES AVISOS Y TABLEROS (15%)', N'ROUND(ISNULL(ep.aut_ValorConcepto15,0) * 0.15 / 1000.0, 0) * 1000', 0, 7, 1),
        (12, 'AUTORRETEICA', 2026, 17, N'TOTAL AUTORRETENCIONES A CARGO', N'ISNULL(ep.aut_ValorConcepto15,0) + ISNULL(ep.aut_ValorConcepto16,0)', 0, 8, 1),
        (13, 'AUTORRETEICA', 2026, 18, N'Menos ANTICIPOS U OTROS', N'ep.aut_ValorConcepto18', 1, 9, 1),
        (14, 'AUTORRETEICA', 2026, 19, N'TOTAL AUTORRETENCION LIQUIDADO', N'ISNULL(ep.aut_ValorConcepto17,0) - ISNULL(ep.aut_ValorConcepto18,0)', 0, 10, 1),
        (15, 'AUTORRETEICA', 2026, 20, N'TOTAL SALDO A FAVOR', N'ep.aut_ValorConcepto20', 1, 11, 1),
        (16, 'AUTORRETEICA', 2026, 21, N'INTERESES', N'ep.aut_ValorConcepto21', 1, 12, 1),
        (17, 'AUTORRETEICA', 2026, 22, N'Mas SANCIONES', N'ep.aut_ValorConcepto22', 1, 13, 1),
        (18, 'AUTORRETEICA', 2026, 23, N'TOTAL A PAGAR EN EL BIMESTRE', N'ISNULL(ep.aut_ValorConcepto19,0) - ISNULL(ep.aut_ValorConcepto20,0)
                     + ISNULL(ep.aut_ValorConcepto21,0) + ISNULL(ep.aut_ValorConcepto22,0)', 0, 14, 1);
    SET IDENTITY_INSERT dbo.[ind_renglones_retencion] OFF;
END
